observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_6d2248c851301d07>
    <urn:graphragprov:unit:u_6ecb56fad21089e9>
    <urn:graphragprov:unit:u_901a2b3c129a6682>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
